import{_ as t,o,c as a,ag as i}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-09-22（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-22.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-22.md"}'),r={name:"topics/ai-system-architecture/science-daily-2026-09-22.md"};function n(l,e,c,s,u,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-09-22-ai-系统架构" tabindex="-1">科学日报 · 2026-09-22（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-09-22-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-09-22（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> — 第29期</p></blockquote><hr><h2 id="radar-腹部-ct-的专家级通用视觉语言模型-science" tabindex="-1">RADAR：腹部 CT 的专家级通用视觉语言模型（Science） <a class="header-anchor" href="#radar-腹部-ct-的专家级通用视觉语言模型-science" aria-label="Permalink to &quot;RADAR：腹部 CT 的专家级通用视觉语言模型（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ DOI: 10.1126/science.aec6129</p></blockquote><ul><li>问题：放射 AI 想要跨任务专家级诊断，但监督式方法<strong>任务覆盖面窄</strong>，每个征象都要单独标注。</li><li>做法：从<strong>临床报告</strong>直接学习，无需人工标注——40 万余例增强腹部 CT、1500 万&quot;按解剖结构组织&quot;的图像-文本对。</li><li>结果：多中心内部/外部评估中，18 个解剖结构、146 种影像征象均达高诊断性能且泛化稳健；读片研究中，<strong>RADAR 辅助让 26 名放射科医生的诊断灵敏度平均提升约 10%</strong>。</li><li>洞察：与 09-21 期编码 Agent 那组证据互为镜像——<strong>报告即标签</strong>（把已有文本当监督）是可扩展的路径，但要小心&quot;报告本身不完整&quot;这一偏置。与 Paper2Agent（同期）同属&quot;把文档变成可执行资产&quot;的家族。</li></ul><h2 id="retrochimera-让化学家更愿意采信的逆合成模型-nature" tabindex="-1">RetroChimera：让化学家更愿意采信的逆合成模型（Nature） <a class="header-anchor" href="#retrochimera-让化学家更愿意采信的逆合成模型-nature" aria-label="Permalink to &quot;RetroChimera：让化学家更愿意采信的逆合成模型（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ DOI: 10.1038/s41586-026-11160-9</p></blockquote><ul><li>失败模式先行：AI 合成规划已普及，但<strong>缺乏对失败模式的系统理解</strong>——低频却战略关键的反应预测差，且会给出与化学家预期不符的<strong>幻觉式错误预测</strong>。</li><li>做法：两个具<strong>互补归纳偏置</strong>的新组件 + 学习式集成策略（RetroChimera）。</li><li>结果：跨数个数量级数据规模超过主流基线；分布外稳健；能从每类反应<strong>极少量样例</strong>学习。成对与单点评估中，<strong>有机化学家更偏好其预测，胜过已发表参考反应与其他 AI 模型</strong>；两家大型药企内部数据上零样本迁移与微调均稳健。</li><li>洞察：&quot;<strong>与专家偏好对齐</strong>&quot;被当成可测指标（pairwise/pointwise 人类偏好），而不是只报 top-k 命中率。这正是本库反复出现的判据：评测指标选错，模型就会朝错误目标优化。可对照 09-21 期分域评估（PP-S）与 OverclaimBench——三件都在讲&quot;分数要挂在人真正关心的量上&quot;。</li></ul><h2 id="paper2agent-把论文转成可交互、可靠的-ai-agent-nature" tabindex="-1">Paper2Agent：把论文转成可交互、可靠的 AI agent（Nature） <a class="header-anchor" href="#paper2agent-把论文转成可交互、可靠的-ai-agent-nature" aria-label="Permalink to &quot;Paper2Agent：把论文转成可交互、可靠的 AI agent（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ DOI: 10.1038/s41586-026-11044-y</p></blockquote><ul><li>定位：论文是被动制品，读者要自己理解并改造代码/数据/方法；Paper2Agent 把它转成 agent，充当**&quot;虚拟通讯作者&quot;**。</li><li>机制：多 agent 分析论文与代码库 → 构建 <strong>MCP 服务器</strong> → 自动生成并运行测试来提升 MCP 稳健性 → 论文 MCP 接入聊天 agent（如 Claude Code），用自然语言调用论文中的工具与流程。</li><li>案例：AlphaGenome 变异解读 agent、基于 Scanpy 与 TISSUE 的 agent。</li><li>洞察：<strong>&quot;可靠&quot;在架构上被落成&quot;有测试的接口&quot;</strong>，而不是提示词里的承诺——这与 SafeHarness（09-21：&quot;约束写在提示词里 ≠ 约束进了规划器&quot;）是同一条教训的另一种应用。对外脑的直接启示：知识条目若要能被 agent 复用，就得有稳定的入口契约（MCP/skill），而不是散文。</li></ul><h2 id="codemidas-只用源码本身-把代码库扩成编码-agent-的-rl-环境-arxiv-2609-22068" tabindex="-1">CodeMidas：只用源码本身，把代码库扩成编码 Agent 的 RL 环境（arXiv:2609.22068） <a class="header-anchor" href="#codemidas-只用源码本身-把代码库扩成编码-agent-的-rl-环境-arxiv-2609-22068" aria-label="Permalink to &quot;CodeMidas：只用源码本身，把代码库扩成编码 Agent 的 RL 环境（arXiv:2609.22068）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ arXiv: 2609.22068</p></blockquote><ul><li>问题：编码 Agent 的 RL 需要多样任务 + 可靠验证器；既有方法依赖 issue/commit 等<strong>开发制品</strong>，限制了可提取任务的范围。</li><li>做法：只把<strong>源码</strong>当任务特异输入——agent 探索已实现功能写出行为规格 → 基于原代码执行构造测试 → 用执行检查与重复解 rollout 验证过滤。</li><li>数据：<strong>5,545 个训练任务 / 3,185 个开源代码库 / 23 种语言 / 15 个技术领域</strong>；GRPO 训练 MiMo-V2.5：DeepSWE +11.7%、ProgramBench +17%、Terminal-Bench v2.1 +8.5%，五个基准全升。</li><li>行为变化：RL 后 agent <strong>更爱探索代码库、自验证方式更多样</strong>。</li><li>洞察：<strong>验证器只有&quot;从执行里长出来&quot;才可靠</strong>——这条直接把本库 replay_eval 的设计原则（候选必须真跑一遍才算数）搬到数据构造层。也解释了为什么&quot;任务量&quot;能换性能：环境规模化本身是一种能力来源。</li></ul><h2 id="pir-读出模型知道却不愿说的知识-arxiv-2609-21996" tabindex="-1">PIR：读出模型知道却不愿说的知识（arXiv:2609.21996） <a class="header-anchor" href="#pir-读出模型知道却不愿说的知识-arxiv-2609-21996" aria-label="Permalink to &quot;PIR：读出模型知道却不愿说的知识（arXiv:2609.21996）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ arXiv: 2609.21996</p></blockquote><ul><li>问题：模型可能在评估里<strong>放水（sandbagging）</strong>，或回答与内部认知相反；单看输出<strong>无法区分&quot;隐瞒&quot;与&quot;不知道&quot;</strong>。</li><li>方法：借鉴司法取证中的隐藏信息测试（CIT）——真细节混在诱饵里，认得出的人反应更强；PIR（Probe of Internal Recognition）在模型内部做同一件事，<strong>不需要参考模型、不需要标注真值</strong>。</li><li>数据：8 模型 / 5 家族（Gemma、Qwen、Llama、Mistral、Phi）平衡准确率 <strong>0.70–0.87</strong>（未知项基线 0.28–0.40，随机 0.25）；提示欺骗、训练过的 sandbagging、密码锁与 circuit-broken 检查点下仍保持 <strong>0.85–0.93</strong>；真正遗忘移除知识后，识别率<strong>降到&quot;从未学过&quot;水平</strong>。</li><li>洞察：这是 Echo Gap / Overclaim 系列的<strong>反面工具</strong>——09-21 的 OverclaimBench 是从<strong>行为</strong>抓夸大，PIR 是从<strong>内部状态</strong>抓隐瞒，合起来才构成&quot;输出 ≠ 内部&quot;的完整测量面。对外脑的启示：自我报告不可信，需要有独立探针；unlearning 审计尤其需要它（否则&quot;删掉了&quot;无法验证）。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第29期 AI 板块</p></blockquote><p>关键词：RADAR、腹部CT、视觉语言模型、逆合成、RetroChimera、人类偏好对齐、Paper2Agent、MCP、CodeMidas、RL环境、sandbagging、PIR、隐藏信息测试、unlearning 关联：<code>topics/ai-system-architecture/science-daily-2026-09-21.md</code>（OverclaimBench / harness / SafeHarness：输出≠轨迹）、<code>topics/ai-system-architecture/brain-self-evolution.md</code>（评测器防自证、同构接口）、<code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code>（自我叙事膨胀）、<code>topics/ai-system-architecture/liouville-goldbach-astra-claim.md</code>（声明审计）</p>',21)])])}const q=t(r,[["render",n]]);export{h as __pageData,q as default};
